module M;
class View
  private _s: ReadOnlySpan<int>;
  public constructor(s: ReadOnlySpan<int>)
    _s := s;     // §9.7 / stdlib §4.16: rejected (no null-source span)
  end constructor; // stdlib §4.14: admitted "when the field's enclosing class
                   //   outlives the borrow source" -- a residual no rule states
  public method First(): int => _s[0];
end View;
class Program
  public static method Main(): int
    using var buf := new OwningBuffer<int>(4);
    var v := new View(buf.AsReadOnlySpan());
    return v.First();
  end Main;
end Program;

class Frame
  private owned _arr: Array<int> := [1, 2, 3, 4];
  public method View(ref s: ArraySpan<int>): ()
    s := _arr.AsSpan();            // receiver-sourced: admitted callee-side
  end View;
  public method Reset(): ()
    _arr := [9];                   // §28.7 drop-on-overwrite disposes the old array
  end Reset;
end Frame;
class Host
  public static method Run(f: Frame): int
    var own: Array<int> := [0];
    var s := own.AsSpan();
    f.View(ref s);                 // pool {f, own}: scope comparison admits; s's set = {f, own}
    f.Reset();                     // kills no traced binding: K5.9 does not engage
    return s[0];                   // reads the freed array's window, no flag (§9.7)
  end Run;
end Host;

class Item
  public method N(): int => 1;
end Item;
class Maker
  private owned _item: Item := new Item();
  public method Get(): Item
    var b := _item;               // receiver-sourced borrow
    var f := lambda() => b;       // clause 1: f's set {this}
    using var it := new Item();   // same block as b
    b := it;                      // local-scope bullet admits; §27.5 shared cell
    return f();                   // reading 3 (formation): {this} -> admitted
  end Get;                        // `it` disposed; caller's Item dangles
end Maker;
// Reading 1 (#5688: union over b's assignments): {this, it} -> rejected.
// In-lambda twin: `var g := lambda() => do b := it; end; g(); return b;`
// -- the body's flow analysis still sources b at `this`.

class Item
  public method N(): int => 1;
end Item;
record Pair(Item: Item?);
class Maker
  public method Make(): Pair
    var p := new Pair(null);      // null-source: contributes nothing
    var f := lambda() => p;       // f's set {} at formation
    using var it := new Item();
    p := new Pair(it);            // same block: admitted; shared cell
    return f();                   // reading 3: carries {} -> admitted
  end Make;                       // `it` disposed; caller's Pair dangles
end Maker;
// Reading 1 (#5688): f's set includes {it} -> rejected at the return.

// inside `public method Make(): [1]Item?`:
var a: [1]Item? := [null];        // null-source
var f := lambda() => a;            // f's set {}
using var it := new Item();
a[0] := it;                         // same block: admitted
return f();                         // reading 3: {} -> admitted; `it` disposed at scope end

// choice Ref Some(item: Item), None; inside `public method Make(): Ref`:
var r := Ref.None;                 // null-source: contributes nothing
var f := lambda() => r;            // f's set {}
using var it := new Item();
r := Ref.Some(it);                 // same block: admitted
return f();                        // reading 3: {} -> admitted; `it` disposed

class Maker
  private owned _xs: Array<int> := [1, 2];
  public method Make(): ArraySpan<int>
    var s := _xs.AsSpan();        // receiver-sourced
    var f := lambda() => s;       // f's set {this}
    var zs: Array<int> := [9];    // same block as s
    s := zs.AsSpan();             // admitted; the shared cell views zs
    return f();                   // reading 3: {this}, §9.7 form 1 -> admitted
  end Make;                       // zs freed: the caller reads a freed window, no flag
end Maker;
// In-lambda twin, no f needed:
//   var g := lambda() => do s := zs.AsSpan(); end;  g();  return s;

class Maker
  public method Make(): () -> int
    var g := lambda() => 0;          // capture-free
    var f := lambda() => g();        // clause 1: g's set, {} at formation
    var xs: Array<int> := [1];
    var s := xs.AsSpan();
    g := lambda() => s[0];           // set {xs}; same block: admitted
    return f;                        // reading 3: f capture-free -> admitted
  end Make;                          // xs freed; f() reads a freed window, no flag
end Maker;
// Reading 1 (#5688): g's set is {} ∪ {xs}, so f's is {xs} -> rejected.

class Item
  public method N(): int => 1;
end Item;
class Holder
  private _f: (() -> int)? := null;
  public method Arm(): ()
    var b: Item? := null;            // no source
    var f := lambda() => b!.N();     // clause 1: set {} at formation
    _f := f;                         // capture-free: admitted at the field
    using var it := new Item();
    b := it;                         // same block: admitted; shared cell (§27.5)
  end Arm;                           // `it` disposed
  public method Fire(): int => _f!();  // N() on a disposed Item (flag fault)
end Holder;
// Reading 1 (#5688): b's set includes `it` -> the field store is rejected.

class Item
  public method N(): int => 1;
end Item;
record Pair(Item: Item?);
class Holder
  private _f: (() -> int)? := null;
  public method Arm(): ()
    var p := new Pair(null);           // null-source: contributes nothing
    var f := lambda() => p.Item!.N();  // set {} at formation
    _f := f;                           // capture-free: admitted
    using var it := new Item();
    p := new Pair(it);                 // same block: admitted (§27.5 shared cell)
  end Arm;                             // `it` disposed
  public method Fire(): int => _f!();  // reads Pair(it) after disposal
end Holder;
// Reading 1 (#5688): p's set includes `it` -> the field store is rejected.

// in class Holder with `private _f: (() -> int)? := null;`:
public method Arm(): ()
  var a: [1]Item? := [null];          // null-source
  _f := lambda() => a[0]!.N();         // set {}: admitted
  using var it := new Item();
  a[0] := it;                          // same block: admitted
end Arm;                               // `it` disposed; _f!() uses it
// Reading 1 (#5688): rejected at the store.

// choice Ref Some(item: Item), None; in class Holder with `_f: (() -> int)?`:
public method Arm(): ()
  var r := Ref.None;                   // null-source
  _f := lambda() => (case r of Some(var i) => i.N(), None => 0);  // set {}
  using var it := new Item();
  r := Ref.Some(it);                   // same block: admitted
end Arm;                               // `it` disposed; _f!() uses it
// Reading 1 (#5688): rejected at the store.

class Maker
  public method Window(a: Array<int>): IEnumerable<int>
    var s := a.AsSpan();                 // carries {a}
    var f := lambda(x: int) => s[0] + x; // clause 1: set {a}
    var zs: Array<int> := [9];           // same block as s
    s := zs.AsSpan();                    // admitted; the cell now views zs
    return a.Select(f);                  // frame carries {a}: parameter-sourced, admitted
  end Window;                            // zs freed; enumeration reads a freed window
end Maker;
// Reading 1 (#5688): f contributes {a, zs} -> rejected at the return.

class Holder
  private _f: (() -> int)? := null;
  public method Arm(): ()
    var g := lambda() => 0;            // capture-free
    var f := lambda() => g();          // set = g's set, {} at formation
    _f := f;                           // capture-free: admitted
    var xs: Array<int> := [1];
    var s := xs.AsSpan();
    g := lambda() => s[0];             // set {xs}; same block: admitted
  end Arm;                             // xs freed
  public method Fire(): int => _f!();  // f -> g -> freed window, no flag
end Holder;
// Reading 1 (#5688): g's set {} ∪ {xs} reaches f -> rejected at the store.

class Item  public property Count: int => 1;  end Item;
class Keep<T>
  private _last: T?;
  public method Put(a: T)  _last := a;  end Put;   // body checked once, class assumption
  public method Last(): T? => _last;
end Keep;
class Holder
  private owned _k: Keep<Object>;
  public constructor() _k := new(); end;
  public method Arm()
    var it := new Item();
    var f: () -> int := lambda() => it.Count;   // source set: `it`'s scope
    _k.Put(f);           // f -> Object at a T-declared param; T := Object is not a function type
  end Arm;               // `it` disposed
  public method Use(): int
    var g := _k.Last() as () -> int;   // clause 5: narrowed from Object, empty set
    return g!();                        // runs the closure over the disposed `it`
  end Use;
end Holder;

class Item  public property Count: int => 1;  end Item;
record Box<T>(V: T);
class Holder
  private _b: Box<Object>?;
  public method Keep()
    var it := new Item();
    var f: () -> int := lambda() => it.Count;   // source set: `it`'s scope
    _b := new Box<Object>(f);  // component declared T, substituted Object: not a function type
  end Keep;                    // `it` disposed; the box carries no tracked source
  public method Use(): int
    var g := _b!.V as () -> int;   // clause 5: narrowed from Object, empty set
    return g!();                    // runs the closure over the disposed `it`
  end Use;
end Holder;

interface IShape
  method Area(): double;
end IShape;

class Sq: IShape
  public method Area(): double => 1.0;
end Sq;

class F
  public async method MakeAsync(): Task<IShape>
    var s: IShape := new Sq();
    await Task.Delay(1);
    return s;   // §30.1 / K3.2 / C.6: consumed marker-free, Pattern A kind 1 -> admitted
  end MakeAsync;
end F;
// §30.1's return-type list + §30.5's rows: Task<IShape> is in no producer row
// (Pattern A names class T) -> the declaration itself is rejected. Same split for
// OwningTask<IShape> (§30.1 'class type T' vs C.6 'class or interface').

class Item
  public method N(): int => 1;
end Item;

record Pair(Item: Item);

class Runner
  public static async method Go(f: () -> Task): Task
    await f();
  end Go;

  public static async method Run(): Task
    using var it := new Item();
    var p := new Pair(it);
    await Go(async lambda() => do
      await Task.Delay(10);
      Console.WriteLine(p.Item.N());   // captured record read after the lambda's await
    end);
  end Run;
end Runner;
// Reading 1 (#5687): p is a local of the lambda body crossing a suspension whose
//   source is a capture from an enclosing scope -> rejected (§30.1).
// Reading 2: p is an async-lambda capture held to settlement -> admitted (K4.3).

class Item
  public method N(): int => 1;
end Item;

class Runner
  public static async method Go(f: () -> Task): Task
    await f();
  end Go;

  public static async method Run(a: Item, b: Item): Task
    var arr: [2]Item := [a, b];          // borrow-bearing inline array, sources a, b
    await Go(async lambda() => do
      await Task.Delay(10);
      Console.WriteLine(arr[0].N());     // captured inline array read after the lambda's await
    end);
  end Run;
end Runner;
// #5687 reading 1: a local of the lambda body across a suspension -> rejected;
// reading 2: a capture held to settlement -> admitted under K4.3.

class Item
  public method N(): int => 1;
end Item;

public choice Ref
  Some(it: Item),
  None;
end Ref;

class Runner
  public static async method Go(f: () -> Task): Task
    await f();
  end Go;

  public static async method Run(x: Item): Task
    var r := Ref.Some(x);
    await Go(async lambda() => do
      await Task.Delay(10);
      case r of Some(i) => Console.WriteLine(i.N()), None => ();   // read after the lambda's await
    end);
  end Run;
end Runner;
// #5687: reject (local across suspension, capture-sourced) or admit (capture held to settlement).

class Runner
  public static async method Later(f: () -> int): Task
    await Task.Delay(10);
    Console.WriteLine(f());          // runs after the caller's Dispose
  end Later;

  public static async method Main(): Task
    var xs: Array<int> := [1, 2, 3];
    var s := xs.AsSpan();
    var t := Later(lambda() => s[0]); // 0148: the frame carries xs; admitted (t does not outlive xs)
    xs.Dispose();                     // K5.9 holders: s dead, no live closure local,
                                      // t is a task local (K6.4: untraced) -> unfrozen
    await t;                          // f() reads xs's freed window: no flag on a span read
  end Main;
end Runner;
// Abandonment twin: Task.FireAndForget(Later(lambda() => s[0])); then xs's scope ends.

