module M;
class Grid
  private owned _buf: OwningBuffer<int>;
  public constructor() _buf := new OwningBuffer<int>(4); end constructor;
  public method Peek(): int
    var s := _buf.AsSpan();             // receiver-sourced span over _buf's current value
    _buf := new OwningBuffer<int>(4);   // C1 store: drop-on-overwrite disposes the viewed buffer;
                                        // a field is not a freeze subject (K5.6), not a K5.9 kill
    return s[0];                        // span read: no flag check -> reads freed storage
  end Peek;
end Grid;

module M;
class Item public constructor() end constructor; end Item;
record Pair(Item: Item);
class Holder
  private owned _keep: Array<Pair>;
  public constructor() _keep := new Array<Pair>(); end constructor;
  public method Arm()
    using var it := new Item();
    var xs: Array<Pair> := [new Pair(it)];  // local; §9.7 scope check admits
    _keep := xs.ToArray();                 // fresh owned copy into an owned field:
  end Arm;                                 // no rule reads its elements' sources;
end Holder;                                // `it` disposed, _keep[0].Item dangles

module M;
class Sink
  private owned _xs: Array<int>;
  public constructor() _xs := new Array<int>(); end constructor;
  public method Take(owned xs: Array<int>) _xs := xs; end Take;
end Sink;
class Program
  public static method Run(sink: Sink)
    var xs: Array<int> := [1, 2, 3];
    var coll: Array<ArraySpan<int>> := [];
    coll.Add(xs.AsSpan());          // admitted: xs's scope encloses coll's (§9.7)
    sink.Take(move xs);             // coll is no K5.5/K5.9 holder: not frozen
    Console.WriteLine(coll[0][0]);  // span read, no flag: storage sink now owns
  end Run;
end Program;

class Gen
  public static method Each(s: ArraySpan<int>): IEnumerable<int>
    for var i in 0..<s.Length do
      yield return s[i];
    end;
  end Each;

  public static method Main()
    var xs: Array<int> := [1, 2, 3];
    var frames: Array<IEnumerable<int>> := [];
    frames.Add(Each(xs.AsSpan()));     // frame carries xs; collection local: not a K5.5 holder
    xs.Dispose();                      // no traced holder -> unfrozen
    for var x in frames[0] do          // the frame reads xs's freed window; no flag
      Console.WriteLine(x);
    end;
  end Main;
end Gen;

class Grid
  private owned _buf: Array<int>;

  public constructor()
    _buf := [1, 2, 3];
  end constructor;

  private static method Each(s: ArraySpan<int>): IEnumerable<int>
    for var i in 0..<s.Length do
      yield return s[i];
    end;
  end Each;

  public method Run()
    var it := Each(_buf.AsSpan());   // frame carries the receiver as the span's source
    _buf := [4, 5, 6];               // slot overwrite: K5.6, unfrozen; disposes the viewed array
    for var x in it do               // reads the freed window; no flag on a span read
      Console.WriteLine(x);
    end;
  end Run;
end Grid;

class Walker
  private owned _it: IEnumerator<int>;

  public constructor(s: ArraySpan<int>)
    _it := Walk(s);                // frame carries s's source (a plain parameter): field-store residual
  end constructor;

  public method Next(): int
    _ := _it.MoveNext();
    return _it.Current;
  end Next;

  private static method Walk(s: ArraySpan<int>): IEnumerator<int>
    for var i in 0..<s.Length do
      yield return s[i];
    end;
  end Walk;
end Walker;

// caller
var xs: Array<int> := [1, 2, 3];
using var w := new Walker(xs.AsSpan());   // span temporary: no span or frame local in this body
xs.Dispose();                              // K5.9: no traced holder -> unfrozen
Console.WriteLine(w.Next());               // the stored frame reads xs's freed window

class Viewer
  private owned _buf: Array<int>;

  public constructor()
    _buf := [1, 2, 3];
  end constructor;

  public method Show()
    var s := _buf.AsSpan();                    // span over the slot's current value
    using var g := new ScopeGuard(lambda() => Console.WriteLine(s[0]));
                                               // s declared before g: admitted, s frozen (K5.7)
    _buf := [4, 5, 6];                         // slot overwrite: K5.6, never frozen; frees the viewed array
  end Show;                                    // g's destructor runs the callback: s[0] reads freed memory
end Viewer;
